// ── ENTITLEMENTS ──────────────────────────────────────────────────────────────
// PKG_CAPS, ORDER_SELECT, computeEntitlements, and mergeEntitlementsGrantOnly
// are imported from ../api/_lib/entitlements.js so the client and the server
// writers share one implementation. fetchOrderEntitlements below is the
// client-side wrapper that queries via the browser Supabase client.

// Fetch every order the account (or, for an invitee, Partner A) owns and fold
// in the profile's own entitlement columns, then union them. Grant-only by
// construction. `partnerAId` is set only for invitees, so they inherit the
// buyer's full package on any device.
async function fetchOrderEntitlements(sb, { userId, email, partnerAId } = {}, profile) {
  if (profile?.is_comp) return computeEntitlements([], profile);
  const rows = [];
  const seen = new Set();
  const add = (data) => {
    for (const r of (data || [])) {
      const k = r.order_num || `${r.pkg_key}:${r.created_at}`;
      if (!seen.has(k)) { seen.add(k); rows.push(r); }
    }
  };
  // The profile's own columns act as an extra grant source (covers accounts
  // whose entitlements were only ever written to the profile, e.g. invitees).
  if (profile) {
    rows.push({
      order_num: null, pkg_key: profile.pkg || null, is_physical: false,
      addon_lmft: profile.addon_lmft, addon_reflection: profile.addon_reflection,
      addon_budget: profile.addon_budget, addon_checklist: profile.addon_checklist,
      addon_intimacy: profile.addon_intimacy, addon_workbook: profile.addon_workbook,
      created_at: null,
    });
  }
  let readFailed = false;
  try {
    if (userId) {
      const { data, error } = await sb.from('orders').select(ORDER_SELECT).eq('user_id', userId);
      if (error) { readFailed = true; console.warn('[Attune] orders read (user_id) failed:', error.message); } else add(data);
    }
    if (email) {
      const { data, error } = await sb.from('orders').select(ORDER_SELECT).eq('buyer_email', email.toLowerCase());
      if (error) { readFailed = true; console.warn('[Attune] orders read (buyer_email) failed:', error.message); } else add(data);
    }
    if (partnerAId) {
      const { data, error } = await sb.from('orders').select(ORDER_SELECT).eq('user_id', partnerAId);
      if (error) { readFailed = true; console.warn('[Attune] orders read (partner) failed:', error.message); } else add(data);
    }
  } catch (e) { readFailed = true; console.warn('[Attune] orders read threw:', e); }
  // A failed read must never look like "no grants". Supabase returns
  // { data: null, error } rather than throwing, so swallowing the error here
  // silently downgraded real accounts to core.
  return { ...computeEntitlements(rows, profile), readFailed };
}

// Resolve the account's entitlements, preferring the server-authoritative blob.
// When there's no blob, or the client's own orders read failed (RLS, network),
// the client cannot be trusted to know what the account owns. In that case ask
// the server, which computes with the service role and bypasses RLS, and wait
// for the answer before rendering. Otherwise refresh the blob in the background.
// POST the recompute and surface whatever went wrong. Previously both call
// sites did `.catch(() => {})` / `r.ok ? r.json() : null`, so a 500 from the
// endpoint disappeared without a trace and the blob silently stayed null.
async function postRecompute(accessToken) {
  try {
    const r = await fetch('/api/recompute-entitlements', {
      method: 'POST', headers: { Authorization: `Bearer ${accessToken}` },
    });
    const body = await r.json().catch(() => null);
    if (!r.ok || !body?.ok) {
      console.error('[Attune] recompute-entitlements failed:', r.status, body?.error || '(no body)');
      return null;
    }
    return body;
  } catch (e) {
    console.error('[Attune] recompute-entitlements threw:', e);
    return null;
  }
}

// The stored `attune_order` is itself a record of granted entitlements. Fold it
// into any resync so a merge can never write back fewer grants than the device
// already had. Without this, a resync that resolved to `core` (RLS filtering an
// invitee's view of Partner A's order, or a failed server recompute) would
// overwrite a correct stored order and strip paid features.
function entFromStoredOrder(o) {
  if (!o) return null;
  return {
    comp: false,
    hasGrant: !!(o.orderNum || o.pkgKey || o.pkg),
    pkg: o.pkgKey || o.pkg || 'core',
    orderNum: o.orderNum || '',
    isPhysical: !!o.isPhysical,
    addonLmft: !!o.addonLmft,
    addonReflection: !!o.addonReflection,
    addonBudget: !!o.addonBudget,
    addonChecklist: !!o.addonChecklist,
    addonIntimacy: !!o.addonIntimacy,
    addonWorkbook: o.addonWorkbook || '',
  };
}

// Workbook state (URL + status) is not an entitlement, so every path that
// rebuilds attune_order from entitlements silently dropped it, and the
// dashboard fell back to "Generating now". Carry it through.
// Bump when the workbook's CONTENT changes (builder or payload), so a cached PDF
// from before the change is re-rendered instead of served stale. v2: reference
// card "Phrase for the two of you" was rendering blank.
const WORKBOOK_CONTENT_VERSION = 2;

function carryWorkbook(order) {
  try {
    const prev = JSON.parse(localStorage.getItem('attune_order') || 'null') || {};
    return {
      ...order,
      workbookUrl:    order.workbookUrl    || prev.workbookUrl    || null,
      workbookStatus: order.workbookStatus || prev.workbookStatus || null,
      workbookVersion: order.workbookVersion || prev.workbookVersion || null,
    };
  } catch { return order; }
}

function loadStoredOrderEnt() {
  try { return entFromStoredOrder(JSON.parse(localStorage.getItem('attune_order') || 'null')); }
  catch { return null; }
}

async function resolveEntitlements(sb, session, profile) {
  let ent = await fetchOrderEntitlements(sb, {
    userId: session?.user?.id,
    email: session?.user?.email,
    partnerAId: (profile?.joined_via_invite && profile?.partner_profile_id) ? profile.partner_profile_id : null,
  }, profile);
  const blob = profile?.entitlements || null;
  // Comp is authoritative on its own: render immediately, never block on the
  // server. Still refresh the stored blob in the background so the DB stays
  // truthful (an early return here is why comp accounts never wrote one).
  if (ent.comp) {
    if (session?.access_token && !blob) postRecompute(session.access_token);
    return ent;
  }
  if (blob) { try { ent = mergeEntitlementsGrantOnly(ent, blob); } catch {} }
  if (!session?.access_token) return ent;
  const mustAwait = !blob || ent.readFailed;
  const drifted = !blob || !sameEntitlements(ent, blob);
  if (!mustAwait && !drifted) return ent;
  const req = postRecompute(session.access_token);
  if (!mustAwait) return ent; // background refresh only
  const res = await req;
  if (res?.ok && res.entitlements) {
    try { ent = mergeEntitlementsGrantOnly(ent, res.entitlements); } catch {}
  }
  return ent;
}

