// Shareable couple type card component

// ── COUPLE MAP SVG COMPONENT ──────────────────────────────────────────────────
function CoupleMapSVG({ myS, partS, userName, partnerName, size = 480 }) {
  const typeInfoA = computeIndividualType(myS);
  const typeInfoB = computeIndividualType(partS);
  const itA = INDIVIDUAL_TYPES[typeInfoA.typeCode];
  const itB = INDIVIDUAL_TYPES[typeInfoB.typeCode];

  // Chart geometry — tighter padding now axis labels are removed
  const pad = 32;
  const VB = 460;
  const cx0 = pad, cy0 = 48, cx1 = VB - pad, cy1 = VB - pad + 48;
  const cw = cx1 - cx0, ch = cy1 - cy0;
  const midX = cx0 + cw / 2, midY = cy0 + ch / 2;
  const r = 14; // corner radius for quadrants

  // Orientation: Open=left, Guarded=right (horizontal); Engage=top, Withdraw=bottom (vertical)
  const toX = (openCoord) => cx0 + (1 - openCoord) * cw;
  const toY = (engageCoord) => cy1 - engageCoord * ch;

  const axA = { x: toX(typeInfoA.openCoord), y: toY(typeInfoA.engageCoord) };
  const axB = { x: toX(typeInfoB.openCoord), y: toY(typeInfoB.engageCoord) };

  // Quadrant gradient colors
  const QG = {
    W: ["#FFE4D6", "#FFD0B8"],
    X: ["#DAE4FF", "#C8D5FF"],
    Y: ["#EAE0FF", "#DDD0FF"],
    Z: ["#E8E6E3", "#DEDAD5"],
  };
  const QC = { W: "#E8673A", X: "#1B5FE8", Y: "#7C3AED", Z: "#6B7280" };
  const QN = { W: "The Initiator", X: "The Anchor", Y: "The Feeler", Z: "The Protector" };

  // Name tag pill dimensions
  const tagH = 22, tagR = 11, tagPad = 10;
  const tagW = (name) => Math.max(name.length * 7.2 + tagPad * 2, 60);
  const tagWA = tagW(userName), tagWB = tagW(partnerName);

  // Tag position — above A, below B, nudged if near edges
  const tagAx = Math.max(cx0 + 4, Math.min(cx1 - tagWA - 4, axA.x - tagWA / 2));
  const tagBx = Math.max(cx0 + 4, Math.min(cx1 - tagWB - 4, axB.x - tagWB / 2));
  const tagAy = axA.y - 38;
  const tagBy = axB.y + 18;

  const idA = `gA_${typeInfoA.typeCode}`;
  const idB = `gB_${typeInfoB.typeCode}`;
  const idQW = "qgW", idQX = "qgX", idQY = "qgY", idQZ = "qgZ";

  return (
    <div style={{ width: "100%" }}>
      {/* SVG Map */}
      <svg viewBox={`0 0 ${VB} ${cy1 + 42}`} style={{ width: "100%", display: "block", overflow: "visible" }} aria-label="Couple map showing partner positions">
        <defs>
          {/* Quadrant gradients */}
          <linearGradient id={idQW} x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor={QG.W[0]}/><stop offset="100%" stopColor={QG.W[1]}/>
          </linearGradient>
          <linearGradient id={idQX} x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor={QG.X[0]}/><stop offset="100%" stopColor={QG.X[1]}/>
          </linearGradient>
          <linearGradient id={idQY} x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor={QG.Y[0]}/><stop offset="100%" stopColor={QG.Y[1]}/>
          </linearGradient>
          <linearGradient id={idQZ} x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor={QG.Z[0]}/><stop offset="100%" stopColor={QG.Z[1]}/>
          </linearGradient>
          {/* Dot radial glows */}
          <radialGradient id={idA} cx="50%" cy="40%" r="50%">
            <stop offset="0%" stopColor={itA.color} stopOpacity="0.5"/>
            <stop offset="100%" stopColor={itA.color} stopOpacity="0"/>
          </radialGradient>
          <radialGradient id={idB} cx="50%" cy="40%" r="50%">
            <stop offset="0%" stopColor={itB.color} stopOpacity="0.5"/>
            <stop offset="100%" stopColor={itB.color} stopOpacity="0"/>
          </radialGradient>
          <filter id="dotShadow" x="-80%" y="-80%" width="260%" height="260%">
            <feDropShadow dx="0" dy="3" stdDeviation="6" floodColor="rgba(0,0,0,0.22)"/>
          </filter>
          <filter id="tagShadow" x="-10%" y="-20%" width="120%" height="140%">
            <feDropShadow dx="0" dy="2" stdDeviation="3" floodColor="rgba(0,0,0,0.18)"/>
          </filter>
        </defs>

        {/* ── QUADRANT FILLS (rounded, each its own rect) ── */}
        <rect x={cx0} y={cy0} width={cw/2} height={ch/2} rx={r} fill={`url(#${idQW})`}/>
        <rect x={midX} y={cy0} width={cw/2} height={ch/2} rx={r} fill={`url(#${idQX})`}/>
        <rect x={cx0} y={midY} width={cw/2} height={ch/2} rx={r} fill={`url(#${idQY})`}/>
        <rect x={midX} y={midY} width={cw/2} height={ch/2} rx={r} fill={`url(#${idQZ})`}/>

        {/* Outer border */}
        <rect x={cx0} y={cy0} width={cw} height={ch} rx={r} fill="none" stroke="#D8D0C8" strokeWidth="1.5"/>

        {/* Centre cross — white then subtle line */}
        <line x1={midX} y1={cy0} x2={midX} y2={cy1} stroke="white" strokeWidth="4"/>
        <line x1={cx0} y1={midY} x2={cx1} y2={midY} stroke="white" strokeWidth="4"/>
        <line x1={midX} y1={cy0} x2={midX} y2={cy1} stroke="#C8C0B8" strokeWidth="1"/>
        <line x1={cx0} y1={midY} x2={cx1} y2={midY} stroke="#C8C0B8" strokeWidth="1"/>

        {/* ── QUADRANT LABELS (letter + name, corner) ── */}
        {/* W: top-left */}
        <text x={cx0 + 14} y={cy0 + 22} fontSize="15" fontWeight="800" fill={QC.W} fontFamily="Georgia,serif" opacity="0.95">W</text>
        <text x={cx0 + 14} y={cy0 + 38} fontSize="11.5" fontWeight="700" fill={QC.W} fontFamily="Arial" opacity="0.8">{QN.W}</text>
        {/* X: top-right */}
        <text x={cx1 - 14} y={cy0 + 22} fontSize="15" fontWeight="800" fill={QC.X} fontFamily="Georgia,serif" textAnchor="end" opacity="0.95">X</text>
        <text x={cx1 - 14} y={cy0 + 38} fontSize="11.5" fontWeight="700" fill={QC.X} fontFamily="Arial" textAnchor="end" opacity="0.8">{QN.X}</text>
        {/* Y: bottom-left */}
        <text x={cx0 + 14} y={cy1 - 24} fontSize="15" fontWeight="800" fill={QC.Y} fontFamily="Georgia,serif" opacity="0.95">Y</text>
        <text x={cx0 + 14} y={cy1 - 10} fontSize="11.5" fontWeight="700" fill={QC.Y} fontFamily="Arial" opacity="0.8">{QN.Y}</text>
        {/* Z: bottom-right */}
        <text x={cx1 - 14} y={cy1 - 24} fontSize="15" fontWeight="800" fill={QC.Z} fontFamily="Georgia,serif" textAnchor="end" opacity="0.95">Z</text>
        <text x={cx1 - 14} y={cy1 - 10} fontSize="11.5" fontWeight="700" fill={QC.Z} fontFamily="Arial" textAnchor="end" opacity="0.8">{QN.Z}</text>

        {/* ── AXIS LABELS ── */}
        {/* Vertical axis: Engage (top) / Withdraw (bottom) */}
        <text x={midX} y={cy0 - 16} textAnchor="middle" fontSize="11" fontWeight="700" fill="#8C7A68" fontFamily="Arial" letterSpacing="2">ENGAGE</text>
        <text x={midX} y={cy1 + 30} textAnchor="middle" fontSize="11" fontWeight="700" fill="#8C7A68" fontFamily="Arial" letterSpacing="2">WITHDRAW</text>
        {/* Horizontal axis: Open (left) / Guarded (right) — rotated to run along each side */}
        <text x={cx0 - 14} y={midY} textAnchor="middle" fontSize="11" fontWeight="700" fill="#8C7A68" fontFamily="Arial" letterSpacing="2" transform={`rotate(-90 ${cx0 - 14} ${midY})`}>OPEN</text>
        <text x={cx1 + 14} y={midY} textAnchor="middle" fontSize="11" fontWeight="700" fill="#8C7A68" fontFamily="Arial" letterSpacing="2" transform={`rotate(90 ${cx1 + 14} ${midY})`}>GUARDED</text>


        {/* ── CONNECTING LINE ── */}
        <line x1={axA.x} y1={axA.y} x2={axB.x} y2={axB.y} stroke="#C0B8B0" strokeWidth="2" strokeDasharray="6,5" opacity="0.75"/>

        {/* ── PARTNER B DOT ── */}
        {/* Glow halo */}
        <circle cx={axB.x} cy={axB.y} r="36" fill={`url(#${idB})`}/>
        {/* Pulse ring */}
        <circle cx={axB.x} cy={axB.y} r="22" fill="none" stroke={itB.color} strokeWidth="1.5" opacity="0.28"/>
        {/* Main dot */}
        <circle cx={axB.x} cy={axB.y} r="15" fill={itB.color} filter="url(#dotShadow)"/>
        <circle cx={axB.x} cy={axB.y} r="15" fill="none" stroke="white" strokeWidth="2.5"/>
        {/* Shine */}
        <circle cx={axB.x - 4} cy={axB.y - 4} r="4.5" fill="white" opacity="0.38"/>
        {/* Name tag pill — below dot */}
        <rect x={tagBx} y={tagBy} width={tagWB} height={tagH} rx={tagR} fill={itB.color} filter="url(#tagShadow)"/>
        <text x={tagBx + tagWB / 2} y={tagBy + 15} textAnchor="middle" fontSize="11" fontWeight="700" fill="white" fontFamily="Arial">{partnerName}</text>
        {/* Tail triangle */}
        <polygon points={`${axB.x},${tagBy} ${axB.x - 5},${tagBy + 6} ${axB.x + 5},${tagBy + 6}`} fill={itB.color}/>

        {/* ── PARTNER A DOT (on top) ── */}
        <circle cx={axA.x} cy={axA.y} r="36" fill={`url(#${idA})`}/>
        <circle cx={axA.x} cy={axA.y} r="22" fill="none" stroke={itA.color} strokeWidth="1.5" opacity="0.28"/>
        <circle cx={axA.x} cy={axA.y} r="15" fill={itA.color} filter="url(#dotShadow)"/>
        <circle cx={axA.x} cy={axA.y} r="15" fill="none" stroke="white" strokeWidth="2.5"/>
        <circle cx={axA.x - 4} cy={axA.y - 4} r="4.5" fill="white" opacity="0.38"/>
        {/* Name tag pill — above dot */}
        <rect x={tagAx} y={tagAy} width={tagWA} height={tagH} rx={tagR} fill={itA.color} filter="url(#tagShadow)"/>
        <text x={tagAx + tagWA / 2} y={tagAy + 15} textAnchor="middle" fontSize="11" fontWeight="700" fill="white" fontFamily="Arial">{userName}</text>
        {/* Tail triangle */}
        <polygon points={`${axA.x},${tagAy + tagH} ${axA.x - 5},${tagAy + tagH - 6} ${axA.x + 5},${tagAy + tagH - 6}`} fill={itA.color}/>
      </svg>

      {/* ── HOW PLACEMENT IS CALCULATED (footnote, not a tile) ── */}
      <div style={{ marginTop: "0.75rem" }}>
        <p style={{ fontSize: "0.72rem", color: "#8C7A68", lineHeight: 1.65, margin: "0 0 0.5rem", fontWeight: 300, fontFamily: BFONT }}>
          Where you each sit on this map is calculated from your responses. Scores for Conflict, Repair, and Stress determine placement on the Engage/Withdraw axis, and Expression, Feedback, and Needs scores determine placement on the Open/Guarded axis. Proximity to an axis line means that partner is more flexible on that dimension.
        </p>
        <p style={{ fontSize: "0.72rem", color: "#8C7A68", lineHeight: 1.65, margin: 0, fontWeight: 300, fontFamily: BFONT }}>
          Two people who think they know their type will almost always land somewhere different than expected.
        </p>
      </div>
    </div>
  );
}

// ── Dashboard step header: large gradient step number + title/sub ──────────
function DashStepHeader({ num, title, sub, active = true, isMobile = false }) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: isMobile ? "0.9rem" : "1.25rem", marginBottom: "1.25rem" }}>
      <div style={{ position: "relative", flexShrink: 0 }}>
        <div style={{ width: isMobile ? 52 : 64, height: isMobile ? 52 : 64, borderRadius: "50%", background: active ? "linear-gradient(135deg, rgba(232,103,58,0.12), rgba(155,93,229,0.12), rgba(27,95,232,0.12))" : "rgba(200,191,180,0.18)", border: active ? "1.5px solid rgba(155,93,229,0.28)" : "1.5px solid rgba(200,191,180,0.5)" }}>
          <svg viewBox="0 0 100 100" width="100%" height="100%" style={{ display: "block" }}>
            <defs>
              <linearGradient id={`dashStepGrad-${num}-${active ? "on" : "off"}`} x1="0" y1="0" x2="1" y2="1">
                {active
                  ? (<><stop offset="0%" stopColor="#E8673A" /><stop offset="50%" stopColor="#9B5DE5" /><stop offset="100%" stopColor="#1B5FE8" /></>)
                  : (<><stop offset="0%" stopColor="#C8BFB4" /><stop offset="100%" stopColor="#B3A693" /></>)}
              </linearGradient>
            </defs>
            <text x="50" y={isMobile ? 64 : 66} textAnchor="middle"
              fontFamily={HFONT} fontWeight="700" fontSize={isMobile ? 57.5 : 62.5}
              fill={`url(#dashStepGrad-${num}-${active ? "on" : "off"})`}>{num}</text>
          </svg>
        </div>
      </div>
      <div style={{ flex: 1, minWidth: 0 }}>
        <h2 style={{ fontFamily: HFONT, fontSize: isMobile ? "1.35rem" : "1.65rem", fontWeight: 700, color: "#0E0B07", lineHeight: 1.1, letterSpacing: "-0.02em", margin: "0 0 0.25rem" }}>{title}</h2>
        <p style={{ fontSize: "0.83rem", color: "#8C7A68", fontFamily: BFONT, fontWeight: 300, lineHeight: 1.55, margin: 0 }}>{sub}</p>
      </div>
    </div>
  );
}

// ── Dashboard Step-3 tile: owned tool, add-on, or article ──────────────────
function DashTile({ color, eyebrow, title, sub, cta, onClick, href, disabled = false }) {
  const inner = (
    <>
      <div style={{ flex: 1, minWidth: 0 }}>
        {eyebrow && <div style={{ fontSize: "0.55rem", letterSpacing: "0.18em", textTransform: "uppercase", color: color, fontWeight: 700, fontFamily: BFONT, marginBottom: "0.3rem" }}>{eyebrow}</div>}
        <div style={{ fontSize: "0.92rem", fontWeight: 700, color: "#0E0B07", fontFamily: BFONT, lineHeight: 1.25, marginBottom: "0.2rem" }}>{title}</div>
        <div style={{ fontSize: "0.78rem", color: "#8C7A68", fontFamily: BFONT, fontWeight: 300, lineHeight: 1.5 }}>{sub}</div>
      </div>
      {cta && <span style={{ fontSize: "0.78rem", fontWeight: 700, color: disabled ? "#B3A693" : color, fontFamily: BFONT, flexShrink: 0, marginLeft: "1rem", whiteSpace: "nowrap" }}>{cta}</span>}
    </>
  );
  const style = { display: "flex", alignItems: "center", background: "white", border: "1.5px solid " + (disabled ? "#EFE7DD" : "#E8DDD0"), borderLeft: "4px solid " + (disabled ? "#E0D6C8" : color), borderRadius: 14, padding: "1rem 1.25rem", cursor: disabled ? "default" : "pointer", textDecoration: "none", transition: "box-shadow .15s", opacity: disabled ? 0.75 : 1 };
  const onEnter = disabled ? undefined : (e) => { e.currentTarget.style.boxShadow = "0 4px 18px rgba(0,0,0,.06)"; };
  const onLeave = disabled ? undefined : (e) => { e.currentTarget.style.boxShadow = "none"; };
  if (href) return <a href={href} style={style} onMouseEnter={onEnter} onMouseLeave={onLeave}>{inner}</a>;
  return <div onClick={disabled ? undefined : onClick} style={style} onMouseEnter={onEnter} onMouseLeave={onLeave}>{inner}</div>;
}

// 10.8 — In Practice guides render as square icon tiles in a grid, not as
// another horizontal row in the stacked list above them.
function GuideSquare({ color = "#9B5DE5", icon, title, sub, href }) {
  return (
    <a href={href}
      style={{ display: "flex", flexDirection: "column", aspectRatio: "1 / 1", background: "white", border: "1.5px solid #E8DDD0", borderRadius: 16, padding: "1.1rem", textDecoration: "none", transition: "box-shadow .15s, border-color .15s" }}
      onMouseEnter={e => { e.currentTarget.style.boxShadow = "0 4px 18px rgba(0,0,0,.06)"; e.currentTarget.style.borderColor = color; }}
      onMouseLeave={e => { e.currentTarget.style.boxShadow = "none"; e.currentTarget.style.borderColor = "#E8DDD0"; }}>
      <div style={{ width: 38, height: 38, borderRadius: 11, background: color + "1f", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, marginBottom: "0.75rem" }}>
        {icon}
      </div>
      <div style={{ fontSize: "0.85rem", fontWeight: 700, color: "#0E0B07", fontFamily: BFONT, lineHeight: 1.3, marginBottom: "0.3rem" }}>{title}</div>
      <div style={{ fontSize: "0.72rem", color: "#8C7A68", fontFamily: BFONT, fontWeight: 300, lineHeight: 1.5 }}>{sub}</div>
      <div style={{ marginTop: "auto", fontSize: "0.75rem", fontWeight: 700, color, fontFamily: BFONT }}>Read →</div>
    </a>
  );
}

// Step 3 tile. One shape for everything the couple can pick up next: an icon,
// a title, a line, and an action. Owned tools carry their product colour; add-ons
// are quieter and show the price on the action.
function GrowSquare({ color = "#9B5DE5", icon, title, sub, cta, onClick, href, disabled = false, muted = false }) {
  const inner = (
    <>
      <div style={{ width: 36, height: 36, borderRadius: 11, background: disabled ? "#F1EBE3" : color + "1f", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, marginBottom: "0.65rem" }}>
        {icon}
      </div>
      <div style={{ fontSize: "0.88rem", fontWeight: 700, color: "#0E0B07", fontFamily: BFONT, lineHeight: 1.3, marginBottom: "0.25rem" }}>{title}</div>
      <div style={{ fontSize: "0.73rem", color: "#8C7A68", fontFamily: BFONT, fontWeight: 300, lineHeight: 1.5 }}>{sub}</div>
      <div style={{ marginTop: "auto", paddingTop: "0.7rem", fontSize: "0.76rem", fontWeight: 700, fontFamily: BFONT, color: disabled ? "#B3A693" : color }}>{cta}</div>
    </>
  );
  const style = {
    display: "flex", flexDirection: "column", minHeight: 152, background: "white",
    border: "1.5px solid " + (disabled ? "#EFE7DD" : "#E8DDD0"), borderRadius: 16, padding: "0.95rem 1rem",
    textDecoration: "none", cursor: disabled ? "default" : "pointer",
    transition: "box-shadow .15s, border-color .15s, transform .15s", opacity: disabled ? 0.8 : 1,
  };
  const onEnter = disabled ? undefined : (e) => {
    e.currentTarget.style.boxShadow = "0 8px 26px rgba(0,0,0,.07)";
    e.currentTarget.style.borderColor = color;
    e.currentTarget.style.transform = "translateY(-2px)";
  };
  const onLeave = disabled ? undefined : (e) => {
    e.currentTarget.style.boxShadow = "none";
    e.currentTarget.style.borderColor = "#E8DDD0";
    e.currentTarget.style.transform = "";
  };
  if (href) return <a href={href} style={style} onMouseEnter={onEnter} onMouseLeave={onLeave}>{inner}</a>;
  return <div onClick={disabled ? undefined : onClick} style={style} onMouseEnter={onEnter} onMouseLeave={onLeave}>{inner}</div>;
}

// Icons for the Step 3 squares.
